    ko: { title:'JWT 디코더', label:'JWT 토큰 붙여넣기', decode:'디코드', header:'헤더', payload:'페이로드', about_title:'JWT 디코더 정보', about_desc:'JSON Web Token (JWT)은 당사자 간에 안전하게 정보를 전송하기 위한 개방형 표준(RFC 7519)입니다. 이 도구는 비밀 키 없이 JWT의 헤더와 페이로드를 디코드할 수 있습니다. 참고: 서명을 검증하지는 않습니다.' },
    es: { title:'Decodificador JWT', label:'Pega tu token JWT', decode:'Decodificar', header:'Encabezado', payload:'Carga útil', about_title:'Acerca del decodificador JWT', about_desc:'JSON Web Token (JWT) es un estándar abierto (RFC 7519) para transmitir información de forma segura. Esta herramienta puede decodificar el encabezado y la carga útil de un JWT sin necesidad de la clave secreta. Nota: solo decodifica, no verifica firmas.' },
    pt: { title:'Decodificador JWT', label:'Cole seu token JWT', decode:'Decodificar', header:'Cabeçalho', payload:'Carga útil', about_title:'Sobre o decodificador JWT', about_desc:'JSON Web Token (JWT) é um padrão aberto (RFC 7519) para transmitir informações com segurança. Esta ferramenta pode decodificar o cabeçalho e a carga útil de um JWT sem precisar da chave secreta. Nota: apenas decodifica, não verifica assinaturas.' },
